let workspaceLanguage=localStorage.getItem('huddl-language')==='ar'?'ar':'en';
const originalText=new WeakMap(),originalAttrs=new WeakMap();
function arabicText(value){
  if(translations[value])return translations[value];
  let m;if((m=value.match(/^Choice (\d+)$/)))return `الاختيار ${m[1]}`;
  if((m=value.match(/^Remove choice (\d+)$/)))return `احذف الاختيار ${m[1]}`;
  if((m=value.match(/^Use color (.+)$/)))return `استخدم اللون ${m[1]}`;
  if((m=value.match(/^(\d+) votes?$/)))return `${m[1]} صوت`;
  if((m=value.match(/^(\d+) departments?$/)))return `${m[1]} أقسام`;
  if((m=value.match(/^(\d+) people$/)))return `${m[1]} أشخاص`;
  if((m=value.match(/^Offline · last seen (.+)$/)))return `غير متصلة · آخر ظهور ${m[1]}`;
  if((m=value.match(/^Closes automatically (.+) your time$/)))return `يغلق تلقائياً ${m[1]} بتوقيتك`;
  if((m=value.match(/^You picked the same answer on (\d+) of (\d+) questions you both shared\.$/)))return `اخترتما نفس الإجابة في ${m[1]} من أصل ${m[2]} أسئلة شاركتماها.`;
  if((m=value.match(/^(\d+) ideas ready\. Choose one to edit\.$/)))return `جاهز ${m[1]} اقتراحات. اختار واحداً للتعديل.`;
  if((m=value.match(/^Database: (Connected|Unknown)$/)))return `قاعدة البيانات: ${m[1]==='Connected'?'متصلة':'غير معروف'}`;
  if((m=value.match(/^Email: (Test mode|Configured|Not configured)$/)))return `الإيميل: ${m[1]==='Configured'?'مُعدّ':m[1]==='Test mode'?'وضع التجربة':'غير مُعدّ'}`;
  if((m=value.match(/^AI: (Configured|Not configured)$/)))return `الذكاء الاصطناعي: ${m[1]==='Configured'?'مُعدّ':'غير مُعدّ'}`;
  if((m=value.match(/^Displays: (\d+) online of (\d+) active · (\d+) never connected$/)))return `الشاشات: ${m[1]} متصلة من ${m[2]} مفعّلة · ${m[3]} لم تتصل بعد`;
  if((m=value.match(/^Checked (.+)$/)))return `آخر فحص ${m[1]}`;
  if((m=value.match(/^(\d+) new seats assigned · (\d+)\/(\d+) in use$/)))return `تم تخصيص ${m[1]} مقاعد جديدة · ${m[2]}/${m[3]} مستخدمة`;
  if((m=value.match(/^Good morning, (.+)$/)))return `صباح الخير، ${m[1]}`;
  if(value.endsWith(' · HR WORKSPACE'))return value.replace(' · HR WORKSPACE',' · مساحة الموارد البشرية');
  if(value.endsWith(' · PEOPLE'))return value.replace(' · PEOPLE',' · الزملاء');
  if(/^\d+ \/ \d+ assigned$/.test(value))return value.replace(' assigned',' مقعد مستخدم');
  if(/^\(\d+ \/ \d+ active\)$/.test(value))return value.replace(' active',' مفعّل');
  return value;
}
