function theme(accent){const hex=/^#[0-9a-f]{6}$/i.test(accent||'')?accent:'#ef473d';const c=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));const mix=(target,amount)=>'#'+c.map((v,i)=>Math.round(v*(1-amount)+target[i]*amount).toString(16).padStart(2,'0')).join('');const light=(c[0]*299+c[1]*587+c[2]*114)/1000>150;document.documentElement.style.setProperty('--company-accent',hex);document.documentElement.style.setProperty('--company-ink',light?'#20201d':'#ffffff');document.documentElement.style.setProperty('--company-tint',mix([255,255,255],.91));document.documentElement.style.setProperty('--company-soft',mix([255,255,255],.72));document.documentElement.style.setProperty('--company-border',mix([30,30,30],.18))}
